#!/usr/bin/env python3
"""gen_route_l.py - writes routes/level-l.txt, the S4b queue's L route (Agent 3, run-2 task 2: rows 7, 20, 23, the
OFF L base s4bL0 and W6 gate A). Built from what lx1 and lx2 showed on devoff4-bin (hidden desktop, virtual tags)."""
import os

HERE = os.path.dirname(os.path.abspath(__file__))
ORANGE = '"Toypad: pad 1 mode 3 lit FF 6E 00"'
L = []
add = L.append
for c in [
    "# build/agent3/toypad/routes/level-l.txt - Agent 3, run-2 task 2: the S4b queue's L route (title -> menu walk -> one",
    "# level load). Generated by gen_route_l.py. Needs the toypad sidecar (queue row \"toypad\":true: it places the virtual",
    "# Batman/Gandalf/Wyldstyle tags 2 s after the C8 all-pads-white line). FUNCTIONAL ONLY (hidden desktop).",
    "# From lx1 (build/agent3/runs/20261122-195210-lx1-devoff4) and lx2 (...-201420-lx2-devoff4):",
    "#   - START at the title does nothing; the A after it opens the front end (220/528, C8 all white, tags placed);",
    "#   - ~8 A presses (~50 s) later the story starts: INSTALL0 probes, profile read, amber fade 99 42 0E (lx2 115 s);",
    "#   - loading, then heavy 3D (1000-13000 draws, up to 1.5M vertices, 10-35 fps) for ~110-155 s, working set",
    "#     ~720 MB -> ~1300 MB: the level load (lx2 ~190-300 s, lx1 ~214-370 s);",
    "#   - then 766/110956 at ~60 fps with the pads cycling a 6-colour rainbow (first orange FF 6E 00 = mark vortex);",
    "#     no input changed it in lx2 except START (787/111292), then A (785/123950); B and a tag re-place did not.",
    "# The route ends itself with 'stop' ~95 s after the vortex mark (run-game closes the game then), so -Seconds is",
    "# only a cap (600). Typical length 430-500 s.",
]:
    add(c)
add("wait_first_frame 240")
add("mark first-frame")
add("sleep 50")
add("mark title")
add("press START")
add("sleep 3")
add("press A                                         # title -> front end (C8 all white); tags 2 s later")
add('wait_log "Toypad: pad 3 mode 1 lit FF FF FF" 25')
add("mark pads-white")
add('wait_log "Toypad listener: LOAD -> pad=3" 20')
add("mark tags-placed")
add("sleep 3")
for i in range(1, 11):
    add("press A")
    add("sleep 5")
    add("mark m%02d" % i)
add('wait_log "lit 99 42 0E" 60                       # story load: amber fade after the profile read')
add("mark story-load")
# A every ~6 s through the load and the heavy-3D part (as in lx1/lx2); each wait ends early on an orange fade
for i in range(1, 31):
    add("press A")
    add("wait_log %s 5" % ORANGE)
add("wait_log %s 240" % ORANGE)
add("mark vortex                                     # the post-load scene: 766/110956, rainbow pads")
add("sleep 15")
add("mark v-idle")
add("press START")
add("sleep 8")
add("mark v-start")
add("press A")
add("sleep 8")
add("mark v-start-a")
add("sleep 30")
add("mark settled")
add("sleep 30")
add("mark end")
add("stop")
out = os.path.join(HERE, "level-l.txt")
with open(out, "w", newline="\r\n") as f:
    f.write("\n".join(L) + "\n")
print("wrote %s (%d lines)" % (out, len(L)))
